// =========================================================================
// CATATAN: ~3350 baris data mock lama (jadwalSem2TI, jadwalHariSenin, dst)
// yang dulu ada di awal file ini SUDAH DIHAPUS — terbukti tidak pernah
// direferensikan di logic manapun setelah migrasi ke database asli
// (data yang sama sudah dipindahkan ke JadwalSeeder.php). Sumber data
// sekarang murni dari window.masterJadwalDB (dikirim dari jadwal.blade.php).
// =========================================================================

// Pengaturan Konfigurasi Lembar Pagination
const itemPerHalaman = 5;
let halamanSekarang = 1;

// Mengambil data jembatan dari Blade
let masterJadwal = window.masterJadwalDB || [];
let dataHasilSaring = [...masterJadwal];

document.addEventListener("DOMContentLoaded", () => {
    // Jalankan penyaringan awal untuk memunculkan seluruh data saat pertama dibuka
    jalankanPenyaringanData();

    // EVENT LISTENER: Tombol "Terapkan" di Dropdown Atas
    const btnTerapkan = document.getElementById("btnFilter");
    if (btnTerapkan) {
        btnTerapkan.addEventListener("click", () => {
            halamanSekarang = 1;
            jalankanPenyaringanData();
        });
    }

    // EVENT LISTENER: Kolom Input Pencarian Teks Ketik Langsung
    const searchInput = document.getElementById("searchInput");
    if (searchInput) {
        searchInput.addEventListener("input", () => {
            halamanSekarang = 1;
            jalankanPenyaringanData();
        });
    }

    // EVENT LISTENER: Tombol Export PDF
    // EVENT LISTENER: Tombol Export PDF
    const btnExportPdf = document.getElementById("exportPdfBtn");
    if (btnExportPdf) {
        btnExportPdf.addEventListener("click", () => {
            exportToPdf(); // Biarkan fungsi klik PDF hanya untuk PDF saja
        });
    }

    // --- FUNGSI OTOMATIS MENGISI DROPDOWN DOSEN ---
    // (Sekarang berada di luar, sehingga langsung dieksekusi saat web dimuat)

    // =========================================================================
    // CATATAN: Blok "MANAGEMENT KONTROL FORM TAMBAH JADWAL BARU" yang dulu ada
    // di sini (buka/tutup modal + submit form via alert()) SUDAH DIHAPUS.
    // Form #formTambahJadwal ini sudah punya handler-nya sendiri di
    // resources/views/jadwal.blade.php (blok <script> setelah window.masterJadwalDB),
    // yang memakai toast + auto-disable dropdown, bukan alert(). Membiarkan
    // handler ini tetap ada membuat submit form terkirim DUA KALI sekaligus
    // (dobel request ke /jadwal/tambah), yang menyebabkan alert() lama dan
    // toast baru muncul bersamaan pada request yang sama. Jangan tambahkan
    // listener submit baru untuk form ini di file jadwal.js — cukup di blade.php.
    // =========================================================================
});

// =========================================================================
// 4. SMART ENGINE AUTOMATION: PENYARINGAN BERLAPIS MULTI-SELECTOR
// =========================================================================
function jalankanPenyaringanData() {
    const selectHari = document.getElementById("filterHari");
    const selectJurusan = document.getElementById("filterJurusan");
    const selectKelas = document.getElementById("filterKelas");
    const selectKategoriSemester = document.getElementById(
        "filterKategoriSemester",
    );
    const selectSemester = document.getElementById("filterSemester");
    const searchInput = document.getElementById("searchInput");

    const fHari = selectHari ? selectHari.value : "Semua";
    const fJurusan = selectJurusan ? selectJurusan.value : "Semua";
    const fKelas = selectKelas ? selectKelas.value : "Semua";
    const fKategori = selectKategoriSemester
        ? selectKategoriSemester.value
        : "Semua";
    const fSemester = selectSemester ? selectSemester.value : "Semua";
    const keyword = searchInput ? searchInput.value.toLowerCase().trim() : "";

    dataHasilSaring = masterJadwal.filter((item) => {
        const cocokHari = fHari === "Semua" || item.hari === fHari;
        const cocokKelas = fKelas === "Semua" || item.kelas === fKelas;

        // Logika baru untuk kategori semester
        const semesterGanjil = ["I", "III", "V", "VII"];
        const semesterGenap = ["II", "IV", "VI", "VIII"];
        const cocokSemester =
            fKategori === "Semua" ||
            (fKategori === "Ganjil" &&
                semesterGanjil.includes(item.semester)) ||
            (fKategori === "Genap" && semesterGenap.includes(item.semester));

        const cocokJurusan = fJurusan === "Semua" || item.jurusan === fJurusan;

        // Filter Semester spesifik (I - VII), terpisah dari Kategori
        // Semester (Ganjil/Genap) di atas — supaya bisa dipilih berbarengan
        // (mis. Kategori "Genap" + Semester "II") untuk hasil paling presisi
        const cocokSemesterSpesifik =
            fSemester === "Semua" || item.semester === fSemester;

        const cocokKeyword =
            keyword === "" ||
            item.matakuliah.toLowerCase().includes(keyword) ||
            item.dosen.toLowerCase().includes(keyword) ||
            item.ruang.toLowerCase().includes(keyword);

        return (
            cocokHari &&
            cocokJurusan &&
            cocokKelas &&
            cocokSemester &&
            cocokSemesterSpesifik &&
            cocokKeyword
        );
    });

    renderTabelJadwal();
    updatePaginationUI();
}

// =========================================================================
// 5. RENDERER ENGINE: SUNTIK DATA SLICE KE DOM HTML JADWAL
// =========================================================================
function renderTabelJadwal() {
    const tbody = document.getElementById("jadwalBody");
    if (!tbody) return;

    tbody.innerHTML = "";

    if (dataHasilSaring.length === 0) {
        tbody.innerHTML = `
      <tr>
        <td colspan="8" style="text-align: center; padding: 50px 20px; color: #667085;">
          <i class="fa-solid fa-calendar-xmark" style="font-size: 36px; margin-bottom: 12px; display: block; color: #d0d5dd;"></i>
          <span style="font-weight: 500; display: block;">Jadwal Tidak Ditemukan</span>
          <small style="color: #98a2b3;">Silakan ubah kombinasi filter atau kata kunci pencarian Anda.</small>
        </td>
      </tr>`;
        return;
    }

    const indexMulai = (halamanSekarang - 1) * itemPerHalaman;
    const indexSelesai = indexMulai + itemPerHalaman;
    const dataPerHalaman = dataHasilSaring.slice(indexMulai, indexSelesai);

    dataPerHalaman.forEach((item, index) => {
        const tr = document.createElement("tr");
        tr.style.animationDelay = `${index * 0.08}s`;

        // Cek apakah admin, jika ya buatkan tombol hapus
        let actionHtml = "";
        if (window.userRole === "admin") {
            actionHtml = `
    <td>
      <button onclick="hapusJadwal(${item.id})" style="background: none; border: none; color: #b30000; cursor: pointer; padding: 5px;" title="Hapus Jadwal">
        <i class="fa-solid fa-trash-can" style="font-size: 16px;"></i>
      </button>
    </td>`;
        }

        tr.innerHTML = `
      <td>${item.hari}</td>
      <td>${item.jam}</td>
      <td>
        <div class="matkul-cell">
          <h4>${item.matakuliah}</h4>
          <span>${item.kodeJam} • ${item.sks} SKS</span>
        </div>
      </td>
      <td>${item.dosen}</td>
      <td><span class="kelas-badge">${item.kelas}</span></td>
      <td>${item.semester}</td>
      <td>${item.ruang}</td>
      <td>${item.jurusan}</td>
      ${actionHtml}
    `;
        tbody.appendChild(tr);
    });

    const infoPagination = document.querySelector(".pagination p");
    if (infoPagination) {
        const entriAkhir = Math.min(
            indexMulai + dataPerHalaman.length,
            dataHasilSaring.length,
        );
        infoPagination.innerText = `Showing ${dataHasilSaring.length === 0 ? 0 : indexMulai + 1} to ${entriAkhir} of ${dataHasilSaring.length} entries`;
    }
}

// =========================================================================
// 6. SMART COMPACT PAGINATION
// =========================================================================
function updatePaginationUI() {
    const containerTombol = document.querySelector(".pagination-buttons");
    if (!containerTombol) return;

    containerTombol.innerHTML = "";
    const totalHalaman = Math.ceil(dataHasilSaring.length / itemPerHalaman);

    if (totalHalaman <= 1) return;

    const delta = 1;
    const range = [];

    for (let i = 1; i <= totalHalaman; i++) {
        if (
            i === 1 ||
            i === totalHalaman ||
            (i >= halamanSekarang - delta && i <= halamanSekarang + delta)
        ) {
            range.push(i);
        }
    }

    let barisAngkaSebelumnya = null;

    range.forEach((i) => {
        if (barisAngkaSebelumnya !== null) {
            if (i - barisAngkaSebelumnya === 2) {
                buatElemenTombolPagination(
                    barisAngkaSebelumnya + 1,
                    containerTombol,
                );
            } else if (i - barisAngkaSebelumnya > 2) {
                const spanEllipsis = document.createElement("span");
                spanEllipsis.innerText = "...";
                spanEllipsis.style.cssText =
                    "padding: 6px 10px; color: #98a2b3; font-size: 13px; font-weight: 500; display: inline-block;";
                containerTombol.appendChild(spanEllipsis);
            }
        }

        buatElemenTombolPagination(i, containerTombol);
        barisAngkaSebelumnya = i;
    });
}

function buatElemenTombolPagination(nomorHalaman, wadahKontainer) {
    const btn = document.createElement("button");
    btn.innerText = nomorHalaman;

    // Deteksi kelas active bawaan CSS aslimu
    if (nomorHalaman === halamanSekarang) {
        btn.classList.add("active-page");
    }

    btn.addEventListener("click", () => {
        halamanSekarang = nomorHalaman;
        renderTabelJadwal();
        updatePaginationUI();
    });

    wadahKontainer.appendChild(btn);
}

// Logo Fakultas Ilmu Komputer UNIKA (base64), dipakai di kop PDF Export.
// Disimpan langsung sebagai teks base64 (bukan file terpisah) supaya
// tidak tergantung path/CORS saat jsPDF memuat gambar.
const LOGO_FIKOM_BASE64 =
    "data:image/png;base64,";

// =========================================================================
// 7. EXPORT PDF ENGINE — Format Grid Institusi (persis PDF resmi kampus)
// =========================================================================
// Urutan tetap supaya tabel PDF rapi berurutan, bukan sesuai urutan input data
const URUTAN_HARI_PDF = ["Senin", "Selasa", "Rabu", "Kamis", "Jumat"];
const URUTAN_KODE_JAM_PDF = [
    "AB",
    "ABC",
    "CD",
    "CDE",
    "DE",
    "DEF",
    "EF",
    "GH",
    "GHI",
    "IJ",
    "IJK",
    "JK",
    "JKL",
];
const URUTAN_JURUSAN_PDF = [
    "Teknik Informatika",
    "Sistem Informasi",
    "Sains Data",
];
const JURUSAN_LABEL_PDF = {
    "Teknik Informatika": "TEKNIK INFORMATIKA S-1",
    "Sistem Informasi": "SISTEM INFORMASI S-1",
    "Sains Data": "SAINS DATA S-1",
};

// Peta Kode Blok Jam -> rentang waktu, dipakai untuk legend "Jam" di bagian
// bawah PDF. Kalau jadwal jam kuliah berubah, sesuaikan manual di sini.
const JAM_LEGEND_PDF = {
    AB: "08.00 - 09.40",
    ABC: "08.00 - 10.30",
    CD: "09.50 - 11.30",
    CDE: "09.50 - 12.20",
    DE: "10.40 - 12.20",
    DEF: "10.40 - 13.10",
    EF: "11.40 - 13.20",
    GH: "14.00 - 15.40",
    GHI: "14.00 - 16.30",
    IJ: "15.50 - 17.30",
    IJK: "15.50 - 18.20",
    JK: "16.40 - 18.20",
    JKL: "16.40 - 19.10",
};

// Mengurutkan array item jadwal berdasarkan Hari lalu Kode Blok Jam,
// supaya tabel per kelompok tersusun rapi (bukan acak sesuai urutan input DB)
function urutkanItemJadwalPdf(items) {
    return [...items].sort((a, b) => {
        const idxHariA = URUTAN_HARI_PDF.indexOf(a.hari);
        const idxHariB = URUTAN_HARI_PDF.indexOf(b.hari);
        if (idxHariA !== idxHariB) return idxHariA - idxHariB;

        const idxJamA = URUTAN_KODE_JAM_PDF.indexOf(a.kodeJam);
        const idxJamB = URUTAN_KODE_JAM_PDF.indexOf(b.kodeJam);
        if (idxJamA !== idxJamB) return idxJamA - idxJamB;

        return String(a.kelas || "").localeCompare(String(b.kelas || ""));
    });
}

function exportToPdf() {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF("l", "mm", "a4");
    const tinggiHalaman = doc.internal.pageSize.getHeight();
    const lebarHalaman = doc.internal.pageSize.getWidth();

    const elKategori = document.getElementById("filterKategoriSemester");
    const fKategori = elKategori ? elKategori.value : "Semua";
    const labelKategori =
        fKategori === "Ganjil"
            ? "GANJIL"
            : fKategori === "Genap"
              ? "GENAP"
              : "";
    const tahunAjaran = "2025/2026"; // TODO: sesuaikan manual tiap ganti T.A.

    const elTglMulai = document.getElementById("inputTglMulaiKuliah");
    const tglMulaiRaw = elTglMulai ? elTglMulai.value : "";
    const tglMulaiText = tglMulaiRaw
        ? new Date(tglMulaiRaw + "T00:00:00").toLocaleDateString("id-ID", {
              day: "numeric",
              month: "long",
              year: "numeric",
          })
        : "...";

    const cetakPada = new Date().toLocaleString("id-ID", {
        day: "2-digit",
        month: "2-digit",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit",
    });

    // ================= KOP / HEADER =================
    // Dipanggil sekali saja di halaman PERTAMA tiap hari. Kalau tabel hari
    // itu meluber ke halaman berikutnya, halaman sambungan TIDAK diberi
    // logo/judul lagi (lihat pemanggilan di bawah).
    function gambarKop() {
        doc.addImage(LOGO_FIKOM_BASE64, "PNG", 12, 6, 22, 22);

        doc.setFont("helvetica", "bold");
        doc.setFontSize(13);
        doc.text(
            `JADWAL KULIAH SEMESTER ${labelKategori} T.A. ${tahunAjaran}`.replace(
                "  ",
                " ",
            ),
            lebarHalaman / 2,
            12,
            { align: "center" },
        );
        doc.setFontSize(11);
        doc.text("FAKULTAS ILMU KOMPUTER", lebarHalaman / 2, 18, {
            align: "center",
        });
        doc.text("UNIVERSITAS KATOLIK SANTO THOMAS", lebarHalaman / 2, 23, {
            align: "center",
        });
        doc.setFontSize(9);
        doc.setFont("helvetica", "normal");
        doc.text(
            "TEKNIK INFORMATIKA - S1, SISTEM INFORMASI - S1 & SAINS DATA-S1",
            lebarHalaman / 2,
            28,
            { align: "center" },
        );

        doc.setFont("helvetica", "normal");
        doc.setFontSize(9);
        doc.text(`Perkuliahan Mulai Tanggal ${tglMulaiText}`, 12, 33);
        doc.text(cetakPada, lebarHalaman - 12, 33, { align: "right" });
    }

    // ================= HEADER TABEL (2 baris, merged) — kolom "Hari" ada
    // lagi di tabel (bukan teks di bawah judul), nilainya diulang tiap
    // baris karena tetap 1 tabel per hari =================
    const kolomHeader = [
        [
            {
                content: "Hari",
                rowSpan: 2,
                styles: { halign: "center", valign: "middle" },
            },
            {
                content: "Jam",
                rowSpan: 2,
                styles: { halign: "center", valign: "middle" },
            },
            {
                content: JURUSAN_LABEL_PDF["Teknik Informatika"],
                colSpan: 5,
                styles: { halign: "center" },
            },
            {
                content: "Jam",
                rowSpan: 2,
                styles: { halign: "center", valign: "middle" },
            },
            {
                content: JURUSAN_LABEL_PDF["Sistem Informasi"],
                colSpan: 5,
                styles: { halign: "center" },
            },
            {
                content: "Jam",
                rowSpan: 2,
                styles: { halign: "center", valign: "middle" },
            },
            {
                content: JURUSAN_LABEL_PDF["Sains Data"],
                colSpan: 5,
                styles: { halign: "center" },
            },
        ],
        [
            "Mata Kuliah/ Kelas",
            "SKS",
            "Dsn",
            "Ruang",
            "Sem",
            "Mata Kuliah/ Kelas",
            "SKS",
            "Dsn",
            "Ruang",
            "Sem",
            "Mata Kuliah/ Kelas",
            "SKS",
            "Dsn",
            "Ruang",
            "Sem",
        ],
    ];

    const columnStylesPerHari = {
        0: { cellWidth: 10, halign: "center", fontStyle: "bold" },
        1: { cellWidth: 10, halign: "center" },
        2: { cellWidth: 44 },
        3: { cellWidth: 7, halign: "center" },
        4: { cellWidth: 7, halign: "center" },
        5: { cellWidth: 12, halign: "center" },
        6: { cellWidth: 7, halign: "center" },
        7: { cellWidth: 10, halign: "center" },
        8: { cellWidth: 44 },
        9: { cellWidth: 7, halign: "center" },
        10: { cellWidth: 7, halign: "center" },
        11: { cellWidth: 12, halign: "center" },
        12: { cellWidth: 7, halign: "center" },
        13: { cellWidth: 10, halign: "center" },
        14: { cellWidth: 44 },
        15: { cellWidth: 7, halign: "center" },
        16: { cellWidth: 7, halign: "center" },
        17: { cellWidth: 12, halign: "center" },
        18: { cellWidth: 7, halign: "center" },
    };

    // Menggambar legend "Dosen" + "Jam" di bawah tabel satu hari. Kalau sisa
    // ruang halaman tidak cukup, pindah ke halaman baru TANPA logo/judul
    // (halaman itu masih sambungan hari yang sama, bukan hari baru).
    function gambarLegend(hari, dosenLegendMap) {
        let posisiY = doc.lastAutoTable.finalY + 8;
        if (posisiY > tinggiHalaman - 35) {
            doc.addPage();
            posisiY = 15;
        }

        doc.setFont("helvetica", "bold");
        doc.setFontSize(9);
        doc.text("Dosen :", 12, posisiY);

        const dosenSorted = [...dosenLegendMap.entries()].sort(
            (a, b) => Number(a[0]) - Number(b[0]),
        );
        const setengah = Math.ceil(dosenSorted.length / 2);
        const kolomKiri = dosenSorted.slice(0, setengah);
        const kolomKanan = dosenSorted.slice(setengah);

        doc.setFont("helvetica", "normal");
        doc.setFontSize(7.5);
        const yMulaiDosen = posisiY + 5;
        kolomKiri.forEach(([id, nama], idx) => {
            doc.text(`${id} : ${nama}`, 12, yMulaiDosen + idx * 4);
        });
        kolomKanan.forEach(([id, nama], idx) => {
            doc.text(`${id} : ${nama}`, 105, yMulaiDosen + idx * 4);
        });

        doc.setFont("helvetica", "bold");
        doc.setFontSize(9);
        doc.text("Jam", 210, posisiY);

        doc.setFont("helvetica", "normal");
        doc.setFontSize(7.5);
        const jamEntries = Object.entries(JAM_LEGEND_PDF);
        const setengahJam = Math.ceil(jamEntries.length / 2);
        jamEntries.slice(0, setengahJam).forEach(([kode, waktu], idx) => {
            doc.text(`${kode} : ${waktu}`, 210, yMulaiDosen + idx * 4);
        });
        jamEntries.slice(setengahJam).forEach(([kode, waktu], idx) => {
            doc.text(`${kode} : ${waktu}`, 250, yMulaiDosen + idx * 4);
        });
    }

    // ================= SUSUN & CETAK TABEL PER HARI (Senin, Selasa, ...) =================
    // Tiap hari dapat halaman sendiri (mulai halaman baru), dengan kop
    // (logo + judul + "HARI : ...") digambar ulang di setiap halamannya.
    let adaData = false;
    let halamanPertama = true;

    URUTAN_HARI_PDF.forEach((hari) => {
        const daftarPerJurusan = URUTAN_JURUSAN_PDF.map((jurusan) =>
            urutkanItemJadwalPdf(
                dataHasilSaring.filter(
                    (item) => item.hari === hari && item.jurusan === jurusan,
                ),
            ),
        );

        const jumlahBaris = Math.max(...daftarPerJurusan.map((l) => l.length));
        if (jumlahBaris === 0) return; // hari ini kosong di semua jurusan, lewati

        adaData = true;

        const bodyRows = [];
        const dosenLegendMap = new Map(); // dosenId -> nama, khusus hari ini

        for (let i = 0; i < jumlahBaris; i++) {
            const row = [];
            // Diulang di tiap baris (bukan rowSpan) — sel gabungan tidak bisa
            // dipotong lintas halaman di jsPDF-autoTable (itu bug lama yang
            // bikin halaman kosong), jadi ditulis ulang tiap baris.
            row.push({
                content: hari.toUpperCase(),
                styles: {
                    halign: "center",
                    valign: "middle",
                    fontStyle: "bold",
                },
            });

            daftarPerJurusan.forEach((list) => {
                const item = list[i];
                if (!item) {
                    row.push("", "", "", "", "", "");
                    return;
                }

                row.push(item.kodeJam);
                row.push(
                    item.kelas
                        ? `${item.matakuliah} (${item.kelas})`
                        : item.matakuliah,
                );
                row.push(item.sks ?? "");
                row.push(item.dosenId ?? "");
                row.push(item.ruang ?? "");
                row.push(item.semester ?? "");

                if (item.dosenId && item.dosen) {
                    dosenLegendMap.set(String(item.dosenId), item.dosen);
                }
            });

            bodyRows.push(row);
        }

        if (!halamanPertama) {
            doc.addPage();
        }
        halamanPertama = false;

        // Kop (logo + judul + "HARI : ...") HANYA digambar sekali di
        // halaman pertama hari ini. Kalau tabel hari ini meluber ke
        // halaman berikutnya, halaman sambungan itu TIDAK diberi logo/
        // judul lagi — cukup lanjutan tabel saja (header kolom tabel tetap
        // otomatis berulang berkat opsi `head` di autoTable).
        gambarKop();

        doc.autoTable({
            startY: 40,
            head: kolomHeader,
            body: bodyRows,
            theme: "grid",
            styles: {
                fontSize: 6.5,
                cellPadding: 1,
                font: "helvetica",
                valign: "middle",
                lineWidth: 0.1,
            },
            headStyles: {
                fillColor: [122, 12, 30],
                textColor: 255,
                halign: "center",
                fontSize: 7,
            },
            columnStyles: columnStylesPerHari,
            margin: { left: 10, right: 10, top: 14 },
        });

        gambarLegend(hari, dosenLegendMap);
    });

    if (!adaData) {
        doc.setFont("helvetica", "normal");
        doc.setFontSize(11);
        doc.text(
            "Tidak ada data jadwal untuk kombinasi filter saat ini.",
            14,
            40,
        );
        doc.save("Jadwal_Perkuliahan_FIKOM_UNIKA.pdf");
        return;
    }

    doc.save("Jadwal_Perkuliahan_FIKOM_UNIKA.pdf");
}

window.hapusJadwal = function (id) {
    if (
        confirm(
            "Apakah Anda yakin ingin menghapus jadwal ini? Tindakan ini tidak dapat dibatalkan.",
        )
    ) {
        const csrfToken = document
            .querySelector('meta[name="csrf-token"]')
            .getAttribute("content");

        fetch(`/jadwal/hapus/${id}`, {
            method: "DELETE",
            headers: {
                "X-CSRF-TOKEN": csrfToken,
                Accept: "application/json",
            },
        })
            .then((response) => response.json())
            .then((result) => {
                if (result.success) {
                    // Hapus data dari array JavaScript (tabel)
                    masterJadwal = masterJadwal.filter((j) => j.id !== id);

                    // PENTING: window.masterJadwalDB juga harus disinkronkan.
                    // Ini sumber data yang dipakai perbaruiOpsiBentrok() di
                    // jadwal.blade.php untuk cek ruangan/dosen bentrok saat
                    // Tambah Jadwal. Kalau tidak ikut dihapus di sini, opsi
                    // ruangan/dosen yang jadwalnya baru saja dihapus masih
                    // akan tetap ditandai "(Terpakai)" / "(Bentrok)" padahal
                    // datanya sudah tidak ada lagi.
                    if (window.masterJadwalDB) {
                        window.masterJadwalDB = window.masterJadwalDB.filter(
                            (j) => j.id !== id,
                        );
                    }

                    // Render ulang tabel
                    halamanSekarang = 1;
                    jalankanPenyaringanData();

                    // Munculkan notifikasi
                    alert(result.message);
                } else {
                    alert(result.message || "Gagal menghapus data.");
                }
            })
            .catch((error) => {
                console.error("Error:", error);
                alert("Terjadi kesalahan koneksi saat menghapus data.");
            });
    }
};
